function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
?>
<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | Leads India</title><meta name="description" content="<?=e(mb_substr((string)($p['description'] ?? $title),0,155))?>"><link rel="canonical" href="https://leadsindia.in/property/<?=rawurlencode($ref)?>"><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-slate-50 text-slate-900"><header class="bg-slate-950 text-white"><div class="max-w-6xl mx-auto px-4 py-4 flex items-center justify-between"><a href="/" class="font-black text-xl">LEADS <span class="text-emerald-400">INDIA</span></a><a href="/properties" class="text-sm font-bold">← Back to Properties</a></div></header><main class="max-w-6xl mx-auto px-4 py-8"><div class="grid lg:grid-cols-[1.5fr_.8fr] gap-7"><section><?php if($photos): ?><div class="grid sm:grid-cols-2 gap-3"><?php foreach(array_slice($photos,0,6) as $i=>$photo): ?><img src="<?=e($photo)?>" alt="<?=e($title)?> photo <?=($i+1)?>" class="w-full h-64 object-cover rounded-2xl border border-slate-200 bg-white"><?php endforeach; ?></div><?php else: ?><div class="h-72 rounded-3xl bg-slate-200 flex items-center justify-center text-slate-500 text-5xl">🏠</div><?php endif; ?><div class="mt-6 bg-white border border-slate-200 rounded-3xl p-6"><div class="flex flex-wrap gap-2 text-xs font-black"><span class="px-3 py-1 rounded-full bg-emerald-100 text-emerald-700">LIVE</span><?php if(!empty($record['verification']['verified'])):?><span class="px-3 py-1 rounded-full bg-blue-100 text-blue-700">VERIFIED</span><?php endif;?></div><h1 class="text-3xl font-black mt-4"><?=e($title)?></h1><div class="mt-4 grid sm:grid-cols-3 gap-3"><div class="p-4 bg-slate-50 rounded-2xl"><div class="text-xs text-slate-500">Price</div><div class="font-black text-lg">₹<?=e($p['price'] ?? 'On request')?></div></div><div class="p-4 bg-slate-50 rounded-2xl"><div class="text-xs text-slate-500">Area</div><div class="font-black text-lg"><?=e($p['area'] ?? '')?></div></div><div class="p-4 bg-slate-50 rounded-2xl"><div class="text-xs text-slate-500">Type</div><div class="font-black text-lg"><?=e($p['type'] ?? '')?></div></div></div><div class="mt-6"><h2 class="font-black text-xl">Property Details</h2><div class="mt-3 grid sm:grid-cols-2 gap-3 text-sm"><div><b>Configuration:</b> <?=e($p['configuration'] ?? '')?></div><div><b>Purpose:</b> <?=e($p['purpose'] ?? '')?></div><div><b>Project/Society:</b> <?=e($p['project_name'] ?? '')?></div><div><b>Location:</b> <?=e(($p['locality'] ?? '').', '.($p['city'] ?? ''))?></div></div></div><div class="mt-6"><h2 class="font-black text-xl">Description</h2><p class="mt-2 text-slate-600 leading-7"><?=nl2br(e($p['description'] ?? ''))?></p></div></div></section><aside class="lg:sticky lg:top-6 self-start"><div class="bg-white border border-slate-200 rounded-3xl p-6 shadow-sm"><div class="text-xs text-slate-500">Listing ID</div><div class="font-mono font-bold mt-1"><?=e($ref)?></div><div class="mt-5 p-4 rounded-2xl bg-amber-50 border border-amber-200"><div class="font-black">Owner contact protected</div><p class="text-sm text-slate-600 mt-1">Owner mobile number is hidden. Buyer enquiries are routed through Leads India.</p></div><a href="https://wa.me/919145597951?text=Hi%20Leads%20India%2C%20I%20am%20interested%20in%20property%20<?=rawurlencode($ref)?>" target="_blank" rel="noopener noreferrer" class="mt-4 block text-center rounded-xl bg-emerald-600 text-white font-black py-3">Enquire on WhatsApp</a><button id="shareBtn" class="mt-3 w-full rounded-xl bg-slate-950 text-white font-black py-3">Share Property</button><div id="shareMsg" class="text-xs text-emerald-600 mt-2 text-center min-h-4"></div></div></aside></div></main><script>document.getElementById('shareBtn').onclick=async()=>{const u=location.href,t=document.title;try{if(navigator.share){await navigator.share({title:t,url:u});}else{await navigator.clipboard.writeText(u);document.getElementById('shareMsg').textContent='Property link copied';}}catch(e){}};</script></body></html>
